class TokenBucket:
    def __init__(self, capacity: float, refill_per_sec: float, clock: callable):
        self.capacity = capacity
        self.refill_per_sec = refill_per_sec
        self.clock = clock
        self._tokens = capacity
        self._last_time = self.clock()

    def _refill(self):
        now = self.clock()
        elapsed = now - self._last_time
        self._tokens += self.refill_per_sec * elapsed
        if self._tokens > self.capacity:
            self._tokens = self.capacity
        self._last_time = now

    def allow(self, cost: float = 1) -> bool:
        self._refill()
        if self._tokens >= cost:
            self._tokens -= cost
            return True
        else:
            return False

    @property
    def tokens(self) -> float:
        self._refill()
        return self._tokens
